Papers.Rockel2026XiFootrule.jensen_profi.type:
∀ μ ∈ Set.Icc 0 2,
  ∀ (v : ↑unitInterval),
    (Verification.jensenLow μ v, Verification.jensenHigh μ v) =
      if ↑v ≤ μ / (2 + μ) then (0, ↑v / (1 - ↑v))
      else if ↑v ≤ 2 / (2 + μ) then (↑v - μ / 2 * (1 - ↑v), ↑v + μ / 2 * ↑v) else (2 - 1 / ↑v, 1)

Papers.Rockel2026XiFootrule.twoParameter.type:
∀ (α β : ℝ) (hα : α ∈ Set.Icc 0 (1 / 2)) (hβ : β ∈ Set.Icc 0 (1 / 2)) (t : ↑unitInterval),
  have B := Verification.diagonalHoleBand α β hα hβ;
  B.columnDensity t = (1 - B.holeLength t) / (1 - β)
